<?php require 'config/functions.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('cart.php');check_csrf();$action=$_POST['action']??'';$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($action==='clear'){unset($_SESSION['cart']);redirect('cart.php');}if(!$id)redirect('cart.php');$stmt=$pdo->prepare('SELECT id,stock FROM products WHERE id=?');$stmt->execute([$id]);$p=$stmt->fetch();if(!$p)redirect('cart.php');$qty=filter_var($_POST['quantity']??1,FILTER_VALIDATE_INT);$qty=$qty===false?1:$qty;$_SESSION['cart']??=[];if($action==='add' && $qty>0 && $p['stock']>0)$_SESSION['cart'][$id]=min((int)$p['stock'],($_SESSION['cart'][$id]??0)+$qty);elseif($action==='update'){if($qty<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min($qty,(int)$p['stock']);}elseif($action==='remove')unset($_SESSION['cart'][$id]);redirect('cart.php');